-- Lieferant "Contec AG" (Abdichtungen, Uetendorf) mit allen Contec-Artikeln; Verkauf = Einkauf / 0.75 (25 % Rabatt auf dem Endkundenpreis).
-- Die zwei Artikel Schutzvlies und EPDM-Folie wechseln von "Knechtgarten" zu Contec. Neu: Sprühkleber, Pressschiene, Service-Techniker, Eck-Ausbildung,
-- Durchbruch/Rohrmanschette, Randschiene. Optionen bei "Folie und Vlies": Eck-Ausbildung, Durchbruch, Randschiene, Service-Techniker.
-- Kofra-Option: Sprühkleber (ca. CHF 8 Einkauf je m2 Wand) und Pressschiene (2 m lang) je Laufmeter Mauer zum Befestigen der Folie.
do $$
declare
  ct uuid := gen_random_uuid(); ot uuid; kg uuid; opt_src uuid; af uuid; opt uuid; kofra uuid; jo jsonb; jz jsonb; s_ut uuid; e_mh uuid;
  a_kleber uuid := gen_random_uuid(); a_press uuid := gen_random_uuid(); a_service uuid := gen_random_uuid(); a_ecke uuid := gen_random_uuid(); a_durch uuid := gen_random_uuid(); a_rand uuid := gen_random_uuid();
  n int;
begin
  select id into ot from offertentyp where name = 'Naturteich/Schwimmteich' and papierkorb_am is null;
  select id into kg from lieferant where name = 'Knechtgarten';
  select ao.id, ao.auswahlfeld_id into opt_src, af from auswahloption ao join auswahlfeld f on f.id = ao.auswahlfeld_id join teilschritt t on t.id = f.teilschritt_id join arbeitsschritt s on s.id = t.arbeitsschritt_id
   where s.offertentyp_id = ot and s.name = 'Folie und Vlies' and ao.name = 'Teichfolie verlegen';
  select ao.id into kofra from auswahloption ao join auswahlfeld f on f.id = ao.auswahlfeld_id join teilschritt t on t.id = f.teilschritt_id join arbeitsschritt s on s.id = t.arbeitsschritt_id
   where s.offertentyp_id = ot and s.name = 'Mauern' and ao.name = 'Kofra';
  select id into s_ut from term where offertentyp_id = ot and systemwert_key = 'form_umfang_teich';
  select id into e_mh from eingabefeld where offertentyp_id = ot and name = 'Mauerhöhe';
  if ot is null or kg is null or opt_src is null or kofra is null or s_ut is null or e_mh is null then raise exception 'Grundlagen nicht gefunden'; end if;
  if exists (select 1 from lieferant where kuerzel = 'CONTEC') then raise exception 'Contec existiert schon'; end if;

  insert into lieferant (id, name, firma, kuerzel, strasse, plz, ort, land, kontaktdaten, logo_url, sync_typ, mwst_satz_pct, preise_inkl_mwst, waehrung_default, minimum_marge_pct, sonderzuschlag_pct, zoll_fracht_zuschlag_pct)
  values (ct, 'Contec AG', 'Contec AG', 'CONTEC', 'Glütschbachstrasse 90', '3661', 'Uetendorf', 'Schweiz',
    '{"fax": null, "mobil": null, "emails": ["info@contec.ch"], "telefon1": "+41 33 346 06 00", "telefon2": null, "internet": "contec.ch"}'::jsonb,
    'data:image/png;base64,', 'manuell', 8.1, false, 'CHF', 0, 0, 0);

  -- bestehende Artikel zu Contec verschieben
  update artikel set lieferant_id = ct, artikelnummer_knecht = 'CONTEC_08.100.80', anmerkung = 'Contec.flex Schutzvlies B. Einkauf 5.05, Verkauf = Einkauf / 0.75. Wird unter und über der Folie verlegt.' where artikelnummer_knecht = 'KNECHT_TEICH_VLIES_800';
  update artikel set lieferant_id = ct, artikelnummer_knecht = 'CONTEC_01.100.31', anmerkung = 'Contec.proof EPDM Water 1.5 mm. Einkauf 31.15, Verkauf = Einkauf / 0.75.' where artikelnummer_knecht = 'KNECHT_TEICH_EPDM_15';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'EPDM-Artikel nicht gefunden'; end if;

  insert into artikel (id, lieferant_id, kategorie, artikelnummer_knecht, artikelnummer_lieferant, bezeichnung, einheit, ep_lieferant, vp_knecht, waehrung, wechselkurs, mwst_satz_pct, anmerkung, sync_easybill, sync_offertentool, sync_webtool, haendischer_abgleich, preis_gesperrt) values
    (a_kleber, ct, 'material', 'CONTEC_05.100.30', '05.100.30', 'Contec.adhesive Sprühkleber UN3501, Füllgewicht 14 kg', 'Stk.', 310.50, round(310.50 / 0.75, 2), 'CHF', 1, 8.1,
      'Gewicht 21 kg. Sprühkleber für Anschlussklebungen, bei Zinkblechen Reinigung erforderlich, auf saugenden Untergründen zweimaliger Auftrag. Verarbeitungs- und Lagerungsvorschriften beachten. Einkauf 310.50, Verkauf = Einkauf / 0.75.', false, false, false, true, false),
    (a_press, ct, 'material', 'CONTEC_03.400.14', '03.400.14', 'Contec.fix Pressschiene Alu hohl, 30 x 3 mm gelocht, L 2.0 m', 'Stk.', 11.75, round(11.75 / 0.75, 2), 'CHF', 1, 8.1,
      'Einkauf 11.75, Verkauf = Einkauf / 0.75.', false, false, false, true, false),
    (a_service, ct, 'material', 'CONTEC_14.500.11', '14.500.11', 'Contec.work Service-Leistung, Techniker pro Tag', 'Tag', 1250, round(1250 / 0.75, 2), 'CHF', 1, 8.1,
      'Tagespauschale inkl. Fahrzeit, Kilometer, Mittagessen und Gebrauch Geräte. Preis pro zusätzlicher Mann CHF 1020.00/Tag. Für die Einweisung von Kunden oder Mithilfe bei den Verlege- und Schweissarbeiten. Einkauf 1250, Verkauf = Einkauf / 0.75.', false, false, false, true, false),
    (a_ecke, ct, 'material', 'CONTEC_ECKE_150', 'ECKE_150', 'Contec Eck-Ausbildung bis 1.50 m hoch (Hersteller)', 'Stk.', 150, round(150 / 0.75, 2), 'CHF', 1, 8.1,
      'Artikelnummer von Contec noch nachtragen. Einkauf 150, Verkauf = Einkauf / 0.75.', false, false, false, true, false),
    (a_durch, ct, 'material', 'CONTEC_DURCHBRUCH', 'DURCHBRUCH', 'Contec Durchbruch / Rohrmanschette für die Folie', 'Stk.', 60, round(60 / 0.75, 2), 'CHF', 1, 8.1,
      'Artikelnummer von Contec noch nachtragen. Einkauf 60, Verkauf = Einkauf / 0.75.', false, false, false, true, false),
    (a_rand, ct, 'material', 'CONTEC_RANDSCHIENE', 'RANDSCHIENE', 'Contec Randschiene', 'm', 12, round(12 / 0.75, 2), 'CHF', 1, 8.1,
      'Artikelnummer von Contec noch nachtragen. Einkauf 12 pro m, Verkauf = Einkauf / 0.75.', false, false, false, true, false);

  -- Optionen bei "Folie und Vlies" (Zusatz, kombinierbar)
  select to_jsonb(o) into jo from auswahloption o where o.id = opt_src;
  select to_jsonb(rz) into jz from ressourcenzeile rz where rz.option_id = opt_src and rz.kategorie = 'personal' order by rz.reihenfolge limit 1;

  opt := gen_random_uuid();
  insert into auswahloption select * from jsonb_populate_record(null::auswahloption, jo || jsonb_build_object('id', opt, 'name', 'Zusatz: Eck-Ausbildung', 'reihenfolge', 2, 'mehrfachauswahl', true,
    'mengenoption', true, 'mengenoption_einheit', 'Stk.', 'mengenoption_standardmenge', 1, 'beschreibung', 'Eck-Ausbildung der Folie (vorgefertigtes Formteil, bis 1.50 m hoch) liefern und einbauen.',
    'hinweistext', 'Menge = Anzahl Ecken.', 'optionsgruppe_id', null, 'optionsgruppe_name', null));
  insert into ressourcenzeile select * from jsonb_populate_record(null::ressourcenzeile, jz || jsonb_build_object('id', gen_random_uuid(), 'option_id', opt, 'reihenfolge', 1, 'kategorie', 'material', 'artikel_id', a_ecke,
    'menge_ausdruck', '{"lit": 1, "_einheit": "Stk."}'::jsonb, 'notiz', null));

  opt := gen_random_uuid();
  insert into auswahloption select * from jsonb_populate_record(null::auswahloption, jo || jsonb_build_object('id', opt, 'name', 'Zusatz: Durchbruch / Rohrmanschette', 'reihenfolge', 3, 'mehrfachauswahl', true,
    'mengenoption', true, 'mengenoption_einheit', 'Stk.', 'mengenoption_standardmenge', 1, 'beschreibung', 'Durchbruch durch die Folie mit Rohrmanschette liefern und abdichten.',
    'hinweistext', 'Menge = Anzahl Durchbrüche.', 'optionsgruppe_id', null, 'optionsgruppe_name', null));
  insert into ressourcenzeile select * from jsonb_populate_record(null::ressourcenzeile, jz || jsonb_build_object('id', gen_random_uuid(), 'option_id', opt, 'reihenfolge', 1, 'kategorie', 'material', 'artikel_id', a_durch,
    'menge_ausdruck', '{"lit": 1, "_einheit": "Stk."}'::jsonb, 'notiz', null));

  opt := gen_random_uuid();
  insert into auswahloption select * from jsonb_populate_record(null::auswahloption, jo || jsonb_build_object('id', opt, 'name', 'Zusatz: Randschiene', 'reihenfolge', 4, 'mehrfachauswahl', true,
    'mengenoption', false, 'beschreibung', 'Randschiene zur Befestigung der Folie am Teichrand liefern und montieren.',
    'hinweistext', 'Länge = Umfang der Teichform (laut Formen-Tool).', 'optionsgruppe_id', null, 'optionsgruppe_name', null));
  insert into ressourcenzeile select * from jsonb_populate_record(null::ressourcenzeile, jz || jsonb_build_object('id', gen_random_uuid(), 'option_id', opt, 'reihenfolge', 1, 'kategorie', 'material', 'artikel_id', a_rand,
    'menge_ausdruck', jsonb_build_object('id', s_ut, 'ref', 'term'), 'notiz', 'Länge = Umfang Teichform'));

  opt := gen_random_uuid();
  insert into auswahloption select * from jsonb_populate_record(null::auswahloption, jo || jsonb_build_object('id', opt, 'name', 'Zusatz: Service-Techniker Contec', 'reihenfolge', 5, 'mehrfachauswahl', true,
    'mengenoption', true, 'mengenoption_einheit', 'Tag', 'mengenoption_standardmenge', 1, 'beschreibung', 'Service-Techniker von Contec für die Einweisung und Mithilfe bei den Verlege- und Schweissarbeiten (Tagespauschale inkl. Fahrzeit, Kilometer, Mittagessen und Geräte).',
    'hinweistext', 'Menge = Anzahl Tage. Pro zusätzlicher Mann Einkauf CHF 1020 pro Tag.', 'optionsgruppe_id', null, 'optionsgruppe_name', null));
  insert into ressourcenzeile select * from jsonb_populate_record(null::ressourcenzeile, jz || jsonb_build_object('id', gen_random_uuid(), 'option_id', opt, 'reihenfolge', 1, 'kategorie', 'material', 'artikel_id', a_service,
    'menge_ausdruck', '{"lit": 1, "_einheit": "Tag"}'::jsonb, 'notiz', null));

  -- Kofra: Folie an die Betonmauer kleben (Sprühkleber, ca. CHF 8 Einkauf je m2 Wand = 0.0258 Gebinde) und mit Pressschiene (2 m) befestigen, je Laufmeter Mauer
  insert into ressourcenzeile select * from jsonb_populate_record(null::ressourcenzeile, jz || jsonb_build_object('id', gen_random_uuid(), 'option_id', kofra, 'reihenfolge', 1, 'kategorie', 'material', 'artikel_id', a_kleber,
    'menge_ausdruck', jsonb_build_object('op', '*', 'args', jsonb_build_array(jsonb_build_object('id', e_mh, 'ref', 'eingabefeld'), jsonb_build_object('lit', 0.0258, '_einheit', 'Stk.'))),
    'notiz', 'Folie auf die Betonmauer kleben: je Laufmeter Mauerhöhe x 0.0258 Gebinde (ca. CHF 8 Einkauf je m² Wand)'));
  insert into ressourcenzeile select * from jsonb_populate_record(null::ressourcenzeile, jz || jsonb_build_object('id', gen_random_uuid(), 'option_id', kofra, 'reihenfolge', 2, 'kategorie', 'material', 'artikel_id', a_press,
    'menge_ausdruck', '{"lit": 0.5, "_einheit": "Stk."}'::jsonb, 'notiz', 'Pressschiene 2 m lang zur Befestigung der Folie am Mauerkopf: 0.5 Stk. je Laufmeter'));
  update auswahloption set hinweistext = 'Beim Anklicken öffnet sich die Skizze: Umfangsstücke der Tiefenzone anhaken (nur gerade). Enthält Sprühkleber und Pressschiene für die Folie an der Betonmauer; die Mauer selber wird separat offeriert.' where id = kofra;
end $$;
